import{H as e,Q as t,ht as n,it as r,nt as i,rt as a,tt as o,yt as s}from"./chunks/framework.CShbgyrC.js";var c=JSON.parse(`{"title":"HighOrderMRI.jl overview","description":"","frontmatter":{},"headers":[],"relativePath":"concepts-overview.md","filePath":"concepts-overview.md","lastUpdated":0}`),l={name:`concepts-overview.md`};function u(e,c,l,u,d,f){let p=s(`VitePressMermaid`);return n(),o(`div`,null,[c[0]||=t(`h1`,{id:`highordermri-jl-overview`,tabindex:`-1`},[a(`HighOrderMRI.jl overview `),t(`a`,{class:`header-anchor`,href:`#highordermri-jl-overview`,"aria-label":`Permalink to “HighOrderMRI.jl overview”`},`​`)],-1),c[1]||=t(`p`,null,[a(`The `),t(`a`,{href:`/HighOrderMRI.jl/v0.1.2/guide/operators`},`algorithm and implementation tree`),a(` separates Explicit from LowRank and lists their public selectors.`)],-1),c[2]||=t(`p`,null,`HighOrderMRI.jl reconstructs MRI data with static off-resonance and dynamic higher-order phase terms. Explicit and LowRank use the same signal model, with different ways to evaluate its encoding operator.`,-1),r(p,{code:`flowchart%20TD%0A%20%20%20%20A%5B%22Measured%20k-space%20data%22%5D%20--%3E%20G%5B%22Iterative%20reconstruction%22%5D%0A%20%20%20%20B%5B%22Measured%20or%20predicted%20dynamic%20fields%22%5D%20--%3E%20C%5B%22Synchronization%20%2B%20field%20preprocessing%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%22Encoding%20with%20off-resonance%20and%20higher-order%20phase%22%5D%0A%0A%20%20%20%20D%20--%3E%20E1%5B%22Explicit%3A%20HighOrderExplicitOp%22%5D%0A%20%20%20%20D%20--%3E%20E2%5B%22LowRank%3A%20HighOrderLowRankOp%22%5D%0A%20%20%20%20E1%20--%3E%20A1%5B%22Array%3A%20CPU%20%2F%20GPU%22%5D%0A%20%20%20%20E1%20--%3E%20A4%5B%22CUDA%20acceleration%22%5D%0A%20%20%20%20A4%20--%3E%20A5%5B%22Direct%20kernel%22%5D%0A%20%20%20%20A4%20--%3E%20A6%5B%22GEMM%20and%20phase-reuse%22%5D%0A%20%20%20%20E2%20--%3E%20A2%5B%22Per-readout%20%2F%20Incremental%20Shared%22%5D%0A%20%20%20%20E2%20--%3E%20A3%5B%22Direct%20Shared%3A%20Per-readout%20%2F%20Global%22%5D%0A%20%20%20%20A1%20--%3E%20G%0A%20%20%20%20A5%20--%3E%20G%0A%20%20%20%20A6%20--%3E%20G%0A%20%20%20%20A2%20--%3E%20G%0A%20%20%20%20A3%20--%3E%20G`}),c[3]||=i(`<p>The two families differ in numerical representation. Explicit selects Array, Direct kernel or GEMM and phase-reuse; LowRank selects Per-readout, Incremental Shared or Direct Shared construction. They retain the same target physical model, with approximation errors assessed separately.</p><h2 id="core-components" tabindex="-1">Core components <a class="header-anchor" href="#core-components" aria-label="Permalink to “Core components”">​</a></h2><h3 id="dynamic-field-encoding" tabindex="-1">Dynamic field encoding <a class="header-anchor" href="#dynamic-field-encoding" aria-label="Permalink to “Dynamic field encoding”">​</a></h3><p>The encoding model combines Cartesian or non-Cartesian sampling, receive-coil sensitivities, static off-resonance, and spatially varying dynamic field terms. The current high-order encoding constructors support real solid-harmonic terms through third order.</p><h3 id="explicit-implementations" tabindex="-1">Explicit implementations <a class="header-anchor" href="#explicit-implementations" aria-label="Permalink to “Explicit implementations”">​</a></h3><p><code>HighOrderExplicitOp</code> selects Array or CUDA acceleration, with Direct kernel and GEMM and phase-reuse in the CUDA acceleration branch. The selector <code>implementation=:kernel</code> retains its existing meaning. Its Array implementation evaluates the phase with CPU or CUDA array operations. Its CUDA implementation uses direct kernels or resident matrix backends, with supported multi-GPU execution. Agreement between these implementations assesses numerical consistency of the software pathways; it is not, by itself, an independent validation of the underlying physical model.</p><h3 id="low-rank-acceleration" tabindex="-1">Low-rank acceleration <a class="header-anchor" href="#low-rank-acceleration" aria-label="Permalink to “Low-rank acceleration”">​</a></h3><p><code>HighOrderLowRankOp</code> selects independent <a href="/HighOrderMRI.jl/v0.1.2/guide/per-readout">Per-readout</a> factors, <a href="/HighOrderMRI.jl/v0.1.2/guide/incremental-shared">Incremental Shared</a> (the existing default), or <a href="/HighOrderMRI.jl/v0.1.2/guide/direct-shared">Direct Shared</a>. Direct Shared has Per-readout and Global strategies, with different coefficient orderings and rank checks. All approximate residual spatial phase. The NFFT evaluates active x/y Fourier terms in 2D and x/y/z terms in 3D; <code>kz*z</code> remains in the 2D residual. NFFT approximation error is separate from factor-construction error. The theory pages distinguish mathematical identities, empirical policies and measured performance.</p><h3 id="validation-strategy" tabindex="-1">Validation strategy <a class="header-anchor" href="#validation-strategy" aria-label="Permalink to “Validation strategy”">​</a></h3><p>Validation is organized hierarchically. Explicit-implementation agreement, low-rank approximation error, independent numerical validation, and physical validation address distinct questions and should be reported separately. The <a href="/HighOrderMRI.jl/v0.1.2/guide/validation">scientific validation strategy</a> defines these evidence levels, and the <a href="/HighOrderMRI.jl/v0.1.2/guide/reconstruction-protocol">reconstruction protocol</a> specifies the conventions that should remain fixed during controlled comparisons.</p>`,10)])}var d=e(l,[[`render`,u]]);export{c as __pageData,d as default};